def dereference(name: str) -> tuple:
    module, name = "", name
    if "." in name: module, name = name.rsplit(".", 1)
    module, name = toModule(module), toModule(name)
    module = ALIASES[MODULE].get(module, module) or MODULE
    
    return (module, name)


def reference(rule: Nonterminal):
    REFERENCES[MODULE].add(rule)


def declare(rule: Nonterminal):
    DECLARATIONS[MODULE].add(rule)


def flip(s: str, exclude: tuple) -> str:
    replace = {".", "/", "_"}.difference(exclude).pop()
    return s.translate({ ord(e) : replace for e in exclude })

def toModule(s: str) -> str:
    return flip(s, {".", "/"}).upper()

def toPath(s: str) -> str:
    return flip(s, {".", "_"}).lower()

def toRequirement(s: str) -> str:
    return flip(s, {"/", "_"}).lower()
    


